//! Tray icons by taskbar theme, recorder state and size, generated by
//! tools/make-icons.mjs (do not edit by hand).

/// The sizes drawn, in pixels.
pub const SIZES: [u32; 6] = [16, 20, 24, 32, 40, 48];

/// The PNG for a taskbar theme ("dark" or "light"), a recorder state ("recording",
/// "waiting", "off" or "attention") and one of `SIZES`.
pub fn png(theme: &str, state: &str, size: u32) -> Option<&'static [u8]> {
    Some(match (theme, state, size) {
        ("dark", "recording", 16) => include_bytes!("../icons/tray/dark-recording-16.png"),
        ("dark", "recording", 20) => include_bytes!("../icons/tray/dark-recording-20.png"),
        ("dark", "recording", 24) => include_bytes!("../icons/tray/dark-recording-24.png"),
        ("dark", "recording", 32) => include_bytes!("../icons/tray/dark-recording-32.png"),
        ("dark", "recording", 40) => include_bytes!("../icons/tray/dark-recording-40.png"),
        ("dark", "recording", 48) => include_bytes!("../icons/tray/dark-recording-48.png"),
        ("dark", "waiting", 16) => include_bytes!("../icons/tray/dark-waiting-16.png"),
        ("dark", "waiting", 20) => include_bytes!("../icons/tray/dark-waiting-20.png"),
        ("dark", "waiting", 24) => include_bytes!("../icons/tray/dark-waiting-24.png"),
        ("dark", "waiting", 32) => include_bytes!("../icons/tray/dark-waiting-32.png"),
        ("dark", "waiting", 40) => include_bytes!("../icons/tray/dark-waiting-40.png"),
        ("dark", "waiting", 48) => include_bytes!("../icons/tray/dark-waiting-48.png"),
        ("dark", "off", 16) => include_bytes!("../icons/tray/dark-off-16.png"),
        ("dark", "off", 20) => include_bytes!("../icons/tray/dark-off-20.png"),
        ("dark", "off", 24) => include_bytes!("../icons/tray/dark-off-24.png"),
        ("dark", "off", 32) => include_bytes!("../icons/tray/dark-off-32.png"),
        ("dark", "off", 40) => include_bytes!("../icons/tray/dark-off-40.png"),
        ("dark", "off", 48) => include_bytes!("../icons/tray/dark-off-48.png"),
        ("dark", "attention", 16) => include_bytes!("../icons/tray/dark-attention-16.png"),
        ("dark", "attention", 20) => include_bytes!("../icons/tray/dark-attention-20.png"),
        ("dark", "attention", 24) => include_bytes!("../icons/tray/dark-attention-24.png"),
        ("dark", "attention", 32) => include_bytes!("../icons/tray/dark-attention-32.png"),
        ("dark", "attention", 40) => include_bytes!("../icons/tray/dark-attention-40.png"),
        ("dark", "attention", 48) => include_bytes!("../icons/tray/dark-attention-48.png"),
        ("light", "recording", 16) => include_bytes!("../icons/tray/light-recording-16.png"),
        ("light", "recording", 20) => include_bytes!("../icons/tray/light-recording-20.png"),
        ("light", "recording", 24) => include_bytes!("../icons/tray/light-recording-24.png"),
        ("light", "recording", 32) => include_bytes!("../icons/tray/light-recording-32.png"),
        ("light", "recording", 40) => include_bytes!("../icons/tray/light-recording-40.png"),
        ("light", "recording", 48) => include_bytes!("../icons/tray/light-recording-48.png"),
        ("light", "waiting", 16) => include_bytes!("../icons/tray/light-waiting-16.png"),
        ("light", "waiting", 20) => include_bytes!("../icons/tray/light-waiting-20.png"),
        ("light", "waiting", 24) => include_bytes!("../icons/tray/light-waiting-24.png"),
        ("light", "waiting", 32) => include_bytes!("../icons/tray/light-waiting-32.png"),
        ("light", "waiting", 40) => include_bytes!("../icons/tray/light-waiting-40.png"),
        ("light", "waiting", 48) => include_bytes!("../icons/tray/light-waiting-48.png"),
        ("light", "off", 16) => include_bytes!("../icons/tray/light-off-16.png"),
        ("light", "off", 20) => include_bytes!("../icons/tray/light-off-20.png"),
        ("light", "off", 24) => include_bytes!("../icons/tray/light-off-24.png"),
        ("light", "off", 32) => include_bytes!("../icons/tray/light-off-32.png"),
        ("light", "off", 40) => include_bytes!("../icons/tray/light-off-40.png"),
        ("light", "off", 48) => include_bytes!("../icons/tray/light-off-48.png"),
        ("light", "attention", 16) => include_bytes!("../icons/tray/light-attention-16.png"),
        ("light", "attention", 20) => include_bytes!("../icons/tray/light-attention-20.png"),
        ("light", "attention", 24) => include_bytes!("../icons/tray/light-attention-24.png"),
        ("light", "attention", 32) => include_bytes!("../icons/tray/light-attention-32.png"),
        ("light", "attention", 40) => include_bytes!("../icons/tray/light-attention-40.png"),
        ("light", "attention", 48) => include_bytes!("../icons/tray/light-attention-48.png"),
        _ => return None,
    })
}
